draw:
function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2, H/2, 50, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.arc(W/2, H/2, 20, 0, 2*Math.PI);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2, H/2-20);
  ctx.lineTo(W/2, H/2-50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2-20, H/2);
  ctx.lineTo(W/2-50, H/2);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2+20, H/2);
  ctx.lineTo(W/2+50, H/2);
  ctx.stroke();
  ctx.font = '24px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = 'black';
  ctx.fillText('TIME', W/2, H/2-70-Math.sin(t)*20);
  ctx.beginPath();
  ctx.arc(W/2, H/2-100-Math.sin(t)*20, 10, 0, 2*Math.PI);
  ctx.stroke();
  ctx.restore();
}
